// Checkout conversion module - auto-optimize offer flow
const express = require('express');
const router = express.Router();

// In-memory conversion tracking
let conversionStats = {
  offersShown: 0,
  offersAccepted: 0,
  revenue: 0
};

// Track offer shown
router.post('/offer-shown', (req, res) => {
  conversionStats.offersShown++;
  res.json({ ok: true });
});

// Track offer accepted (conversion)
router.post('/offer-accepted', (req, res) => {
  conversionStats.offersAccepted++;
  conversionStats.revenue += req.body.amount || 0;
  res.json({ ok: true });
});

// Get conversion stats
router.get('/stats', (req, res) => {
  const rate = conversionStats.offersShown > 0 ? (conversionStats.offersAccepted / conversionStats.offersShown) : 0;
  res.json({
    offersShown: conversionStats.offersShown,
    offersAccepted: conversionStats.offersAccepted,
    conversionRate: rate,
    revenue: conversionStats.revenue
  });
});

// Reset stats (for testing)
router.post('/reset', (req, res) => {
  conversionStats = { offersShown: 0, offersAccepted: 0, revenue: 0 };
  res.json({ ok: true });
});

module.exports = router;
